  max-width: 980px;
  margin: 2rem auto;
  padding: 1rem;
  color: #173642;
}

section {
  border: 1px solid #d3dfe4;
  border-radius: 18px;
  background: white;
  padding: 1.5rem;
  margin: 1.5rem 0;
}

h1 {
  font-size: 1.8rem;
}

h2 {
  font-size: 1.25rem;
}

article {
  padding: 1rem;
  background: #f3f6f6;
  border-radius: 12px;
  margin: 1rem 0;
  overflow-wrap: anywhere;
}

.notice {
  padding: 1rem;
  background: #e8f1ef;
  border-radius: 10px;
}

.actions {
  display: flex;
  gap: 0.7rem;
  flex-wrap: wrap;
  margin: 0.8rem 0;
}

label {
  display: block;
  margin: 0.7rem 0;
}

input, textarea {
  display: block;
  max-width: 100%;
  padding: 0.6rem;
  margin-top: 0.3rem;
}

textarea {
  width: 100%;
  min-height: 5rem;
}

button {
  padding: 0.7rem 1rem;
  border: 0;
  border-radius: 8px;
  background: #15546a;
  color: white;
  cursor: pointer;
}

button:disabled {
  opacity: 0.5;
  cursor: default;
}

fieldset {
  border: 1px solid #d3dfe4;
  border-radius: 10px;
  padding: 1rem;
}

summary {
  cursor: pointer;
  margin-top: 1rem;
}

[role=alert] {
  color: #992d25;
}

.waiver-reason {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.document-shell.embedded {
  max-width: none;
  margin: 0;
  padding: 0;
