import {Component,Input} from '@angular/core';import {CommonModule} from '@angular/common';import {LanguageService} from '../services/language.service';import {MessageNotificationsService} from './message-notifications.service';import {unreadCount} from './message-unread';
const COPY:Record<string,string>={fr:'messages non lus',en:'unread messages',es:'mensajes sin leer',it:'messaggi non letti',de:'ungelesene Nachrichten',nl:'ongelezen berichten',ru:'непрочитанных сообщений'};
@Component({selector:'app-message-badge',standalone:true,imports:[CommonModule],template:`<ng-container *ngIf="notifications.summary|async as summary"><span *ngIf="count(summary) as n" class="unread-sticker" role="status" aria-live="polite" [attr.aria-label]="n+' '+label()">{{n>99?'99+':n}}</span></ng-container>`,styles:[`:host{position:absolute;top:-10px;right:-10px;z-index:2;pointer-events:none;display:block}.unread-sticker{display:grid;place-items:center;min-width:24px;height:24px;box-sizing:border-box;padding:0 5px;border:2px solid white;border-radius:999px;background:#d92d20!important;color:white!important;font:700 12px/1 sans-serif!important;box-shadow:0 2px 6px #0004;white-space:nowrap}`]})
export class MessageBadgeComponent {
 @Input()type='';@Input()assetId='';constructor(public notifications:MessageNotificationsService,public language:LanguageService){}count(summary:any){return unreadCount(summary,this.type,this.assetId);}label(){return COPY[this.language.currentLanguage]||COPY.en;}
}
