import {portfolioCover} from '../services/management-entry.service';
import {Component,OnInit} from '@angular/core';import {CommonModule} from '@angular/common';import {RouterModule} from '@angular/router';import {HttpClient} from '@angular/common/http';import {firstValueFrom} from 'rxjs';import {StoreDbService} from 'godigital-lib';import {signInWithCustomToken} from 'firebase/auth';
import {AssetAccessService} from '../services/asset-access.service';import {dedicatedAsset} from '../services/asset-domain';import {ReservationAuthService} from '../services/reservation-auth.service';
@Component({selector:'app-site-management-home',standalone:true,imports:[CommonModule,RouterModule],templateUrl:'./site-management.component.html',styleUrls:['./site-management.component.scss']})
export class SiteManagementComponent implements OnInit{scope=dedicatedAsset();base='';ctx:any;title='Mon espace';name='';status='Connexion…';failed=false;
cover=portfolioCover;ready=false;path(a:any,tail:string){return '/'+encodeURIComponent(a.assetType)+'/'+encodeURIComponent(a.id)+'/'+tail;}managed:any[]=[];changeAsset(e:Event){const [t,id]=(e.target as HTMLSelectElement).value.split('/');location.assign('/site-management?type='+encodeURIComponent(t)+'&id='+encodeURIComponent(id));}
constructor(public access:AssetAccessService,private http:HttpClient,private store:StoreDbService,private auth:ReservationAuthService){}
async ngOnInit(){try{const a=this.scope;if(!a)throw Error();this.base='/'+a.assetType+'/'+a.assetId;let session:any;try{session=await firstValueFrom(this.http.post<any>('/api/management-session',{}));}catch(e:any){if(e.status!==401)throw e;}
if(session){const s:any=this.store;let auth=s.firebaseauth||s.firebaseAuth||s.auth;for(let i=0;!auth&&i<80;i++){await new Promise(r=>setTimeout(r,100));auth=s.firebaseauth||s.firebaseAuth||s.auth;}if(!auth)throw Error();await (auth.signInWithCustomToken?auth.signInWithCustomToken(session.token):signInWithCustomToken(auth,session.token));}
const headers=await this.auth.headers(),ctx=await firstValueFrom(this.http.get<any>('/api/me/context',{headers,params:{type:a.assetType,id:a.assetId}}));if(!ctx.ownsAsset&&!(ctx.isConcierge&&Object.values(ctx.managementPermissions||{}).some(Boolean)))throw Error();this.title=ctx.ownsAsset?'Espace propriétaire':'Espace concierge';this.name=location.hostname.split('.')[0];this.ctx=ctx;this.access.rememberSiteMode('owner');this.status='';if(ctx.ownsAsset){const list=await firstValueFrom(this.http.get<any[]>('/api/owner/listings',{headers}));this.managed=list.filter(x=>!x.deletedAt&&x.ownerId===ctx.uid);this.ready=true;}}catch{if(this.ctx){this.status='Impossible de charger les annonces. Rechargez la page pour réessayer.';return;}this.status='Session expirée ou accès indisponible pour ce bien.';this.failed=true;}}}
