import {Component} from '@angular/core';import {CommonModule} from '@angular/common';import {HttpClient} from '@angular/common/http';import {firstValueFrom} from 'rxjs';import {getMessaging,getToken,deleteToken,isSupported} from 'firebase/messaging';import {ReservationAuthService} from '../services/reservation-auth.service';import {AssetAccessService} from '../services/asset-access.service';import {StoreDbService} from 'godigital-lib';
@Component({standalone:true,imports:[CommonModule],selector:'app-push-button',template:`<aside *ngIf="access.authenticatedUid" class="gd-push"><button (click)="change()" [disabled]="busy">{{active?'Désactiver les notifications':'Activer les notifications'}}</button><small role="status">{{note}}</small></aside>`})
export class PushButtonComponent{busy=false;note='';get active(){try{return localStorage.getItem('gd.push.uid')===this.access.authenticatedUid;}catch{return false;}}constructor(public access:AssetAccessService,private auth:ReservationAuthService,private store:StoreDbService,private http:HttpClient){}
async change(){this.busy=true;try{if(!('Notification' in window)||!('serviceWorker' in navigator)){this.note='Sur iPhone, installez GoDirect sur l’écran d’accueil puis ouvrez son icône.';return;}
const off=this.active;if(!off&&await Notification.requestPermission()!=='granted'){this.note='Autorisez les notifications dans les réglages de votre appareil.';return;}
if(!await isSupported())throw Error();const {key}=await firstValueFrom(this.http.get<any>('/api/push/config'));if(!key){this.note='Notifications non configurées sur le serveur.';return;}
const s:any=this.store,auth=s.firebaseauth||s.firebaseAuth||s.auth;const messaging=getMessaging(auth.app?._delegate||auth.app);await navigator.serviceWorker.register('/godirect-sw.js',{scope:'/'});const reg=await navigator.serviceWorker.ready;const token=await getToken(messaging,{vapidKey:key,serviceWorkerRegistration:reg});
await firstValueFrom(this.http.post('/api/push/device',{token,enabled:!off},{headers:await this.auth.headers()}));
if(off){await deleteToken(messaging);localStorage.removeItem('gd.push.uid');}else localStorage.setItem('gd.push.uid',this.access.authenticatedUid);this.note=off?'Notifications désactivées.':'Notifications activées sur cet appareil.';}catch{this.note='Activation indisponible. Vérifiez votre session et les réglages du téléphone.';}finally{this.busy=false;}}}
