  display: block;
}

.owner-dashboard {
  max-width: 1200px;
  padding: 36px 24px 60px;
  margin: auto;
  color: #103f68;
}

.dashboard-heading, .section-heading, .reservation-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 24px;
}

.eyebrow {
  text-transform: uppercase;
  font-size: 11px;
  letter-spacing: 2px;
  font-weight: 700;
}

h1 {
  font: 400 clamp(30px, 4vw, 48px)/1.2 Georgia, serif;
  margin: 12px 0;
}

h2 {
  font-size: 20px;
  margin: 0 0 14px;
}

h3 {
  font-size: 16px;
  margin: 0;
}

p {
  line-height: 1.6;
  color: #526b80;
}

.dashboard-actions {
  display: flex;
  gap: 14px;
  align-items: center;
  flex-wrap: wrap;
}

a {
  color: #103f68;
}

button, .button {
  display: inline-block;
  border: 0;
  border-radius: 9px;
  background: #103f68;
  color: white;
  padding: 12px 16px;
  text-decoration: none;
  font: 600 13px/1.4 Arial, sans-serif;
  cursor: pointer;
}

.secondary {
  background: white;
  color: #103f68;
  border: 1px solid #c9d8e5;
}

.metrics {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 18px;
  margin: 28px 0;
}

.metrics a {
  padding: 24px;
  background: white;
  border: 1px solid #dbe5ed;
  border-radius: 14px;
  text-decoration: none;
}

.metrics span {
  font-size: 13px;
}

.metrics strong {
  display: block;
  font-size: 36px;
  margin-top: 14px;
}

.panel {
  background: white;
  border: 1px solid #dbe5ed;
  border-radius: 14px;
  padding: 25px;
  margin-bottom: 24px;
}

.management-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}

.attention {
  padding: 24px;
  background: #fff3e5;
  border: 1px solid #edc295;
  border-radius: 14px;
  margin-bottom: 24px;
}

.attention p {
  margin: 8px 0;
}

.attention h2 {
  color: #854309;
}

.panel small {
  display: block;
  margin: 6px 0;
  color: #526b80;
}

.panel .button {
  margin-top: 15px;
}

.needs-setup {
  color: #854309;
}

.reservation-row {
  padding: 18px 0;
  border-top: 1px solid #dbe5ed;
}

.reservation-row .button {
  margin-top: 0;
}

.table-scroll {
  overflow: auto;
}

table {
  border-collapse: collapse;
  min-width: 680px;
  width: 100%;
  font-size: 13px;
}

td, th {
  text-align: left;
  padding: 18px 12px;
  border-bottom: 1px solid #dbe5ed;
  line-height: 1.6;
}

.error {
  background: #fff0ed;
  color: #862c20;
  padding: 14px;
  border-radius: 8px;
}

button:disabled {
  opacity: 0.6;
  cursor: wait;
}

a:focus-visible, button:focus-visible {
  outline: 3px solid #c0641b;
  outline-offset: 3px;
}

#owner-reservations {
  scroll-margin-top: 140px;
}

@media (max-width: 800px) {
  .metrics {
    grid-template-columns: 1fr 1fr;
  }
  .dashboard-heading, .section-heading, .reservation-row {
    align-items: flex-start;
    flex-direction: column;
  }
  .management-grid {
    grid-template-columns: 1fr;
    gap: 0;
  }
}
@media (max-width: 440px) {
  .owner-dashboard {
    padding: 24px 16px;
  }
  .metrics {
    gap: 10px;
  }
  .metrics a {
    padding: 16px;
  }
  .panel {
    padding: 20px 16px;
  }
}
.offer-summary {
  padding: 20px 24px;
  background: #fff3e5;
  border: 1px solid #edc295;
  border-radius: 14px;
  margin: 24px 0;
}

.offer-summary > strong {
  font-size: 22px;
}

.offer-summary details {
  margin-top: 15px;
}

.offer-summary summary {
  cursor: pointer;
  font-weight: 700;
}

.assets-panel .section-heading p {
  margin: 4px 0 0;
}

.asset-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 18px;
  margin: 20px 0 24px;
}

.asset-card {
  border: 1px solid #dbe5ed;
  border-radius: 14px;
  overflow: hidden;
  background: #fafdff;
  box-shadow: 0 5px 18px rgba(16, 63, 104, 0.05);
}

.asset-main {
  display: block;
  padding: 22px;
  text-decoration: none;
  color: #103f68;
  transition: background 0.15s ease, transform 0.15s ease;
}

.asset-main:hover {
  background: #f1f7fb;
}

.asset-card-heading {
  display: flex;
  justify-content: space-between;
  gap: 18px;
}

.asset-card h3 {
  font-size: 20px;
  margin: 5px 0;
}

.asset-type {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 1.2px;
  color: #60788d;
  font-weight: 700;
}

.edit-arrow {
  font-size: 24px;
}

.asset-statuses {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-top: 18px;
}

.asset-statuses span {
  font-size: 12px;
  font-weight: 700;
  padding: 6px 9px;
  border-radius: 999px;
  background: #fff0df;
  color: #84430a;
}

.asset-statuses span.ok {
  background: #e4f5eb;
  color: #17623b;
}

.expiry {
  font-size: 12px;
  margin: 12px 0 0;
}

.warning-text {
  color: #854309;
}

.asset-actions {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  padding: 16px 22px;
  border-top: 1px solid #dbe5ed;
  background: #fff;
}

.asset-actions .button {
  margin: 0;
  padding: 9px 12px;
}

.asset-actions .subscription-button {
  background: #c0641b;
}

.asset-actions > a:not(.button) {
  font-size: 13px;
}

@media (max-width: 800px) {
  .asset-grid {
    grid-template-columns: 1fr;
  }
}
.asset-filters {
  display: grid;
  grid-template-columns: minmax(150px, 1fr) minmax(150px, 1fr) minmax(220px, 2fr);
  gap: 14px;
  margin: 22px 0;
  padding: 18px;
  border: 1px solid #dbe5ed;
  border-radius: 12px;
  background: #f7fafc;
}

.asset-filters label {
  display: flex;
  flex-direction: column;
  gap: 7px;
  font-size: 12px;
  font-weight: 700;
}

.asset-filters select, .asset-filters input {
  width: 100%;
  box-sizing: border-box;
  border: 1px solid #b8cad8;
  border-radius: 8px;
  background: white;
  color: #103f68;
  padding: 10px 11px;
  font: 14px Arial, sans-serif;
}

.empty-filter {
  padding: 20px;
  border-radius: 10px;
  background: #f7fafc;
  text-align: center;
}

@media (max-width: 800px) {
  .asset-filters {
    grid-template-columns: 1fr;
  }
