  display: block;
  color: #103f68;
  font-family: Inter, "Segoe UI", Arial, sans-serif;
}

.owner-site {
  max-width: 1296px;
  margin: 0 auto 56px;
  padding: 42px;
  border: 1px solid #dce5db;
  border-radius: 24px;
  background: #f0f4e8;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.05fr);
  gap: 48px;
  scroll-margin-top: 30px;
}

.eyebrow {
  font-size: 11px;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  font-weight: 650;
  margin: 0 0 18px;
}

.site-intro h2 {
  font: 400 clamp(30px, 3vw, 42px)/1.18 Georgia, serif;
  margin: 0 0 20px;
}

.lead {
  font-size: 14px;
  line-height: 1.85;
  color: #405d6e;
  margin-bottom: 22px;
}

.address-example {
  background: #fff;
  border: 1px solid #dbe3d4;
  border-radius: 12px;
  padding: 17px 20px;
  margin-bottom: 23px;
}

.address-example > span {
  display: block;
  font-size: 11px;
  color: #526b80;
  margin-bottom: 9px;
}

.address-example strong {
  display: block;
  font-size: clamp(16px, 2vw, 23px);
  overflow-wrap: anywhere;
}

.address-example p {
  font-size: 12px;
  line-height: 1.7;
  color: #526b80;
  margin: 10px 0 0;
}

.site-cta {
  background: #103f68;
  color: white;
  border: 0;
  border-radius: 11px;
  padding: 14px 22px;
  font: 600 13px/1.4 Inter, "Segoe UI", Arial, sans-serif;
  cursor: pointer;
}

.site-cta:focus-visible {
  outline: 3px solid #b36d25;
  outline-offset: 4px;
}

.pricing {
  font-size: 12px;
  line-height: 1.8;
  color: #526b80;
  margin: 16px 0 0;
}

.site-benefits {
  align-self: center;
  min-width: 0;
}

.feature-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 15px;
}

.feature-grid article {
  background: rgba(255, 255, 255, 0.7019607843);
  border-radius: 14px;
  padding: 20px;
}

.feature-number {
  font: 400 23px Georgia, serif;
  color: #6e8463;
}

.feature-grid h3 {
  font-size: 15px;
  line-height: 1.4;
  margin: 12px 0 10px;
}

.feature-grid p {
  font-size: 12px;
  line-height: 1.8;
  color: #526b80;
  margin: 0;
}

.publication {
  font-size: 12px;
  line-height: 1.8;
  color: #526b80;
  margin: 18px 0 0;
}

@media (max-width: 1400px) {
  .owner-site {
    margin-left: 5vw;
    margin-right: 5vw;
  }
}
@media (max-width: 900px) {
  .owner-site {
    grid-template-columns: 1fr;
    gap: 28px;
    padding: 30px;
  }
}
@media (max-width: 480px) {
  .owner-site {
    padding: 25px;
  }
  .feature-grid {
    grid-template-columns: 1fr;
  }
  .feature-grid article {
    padding: 17px;
  }
