  display: block;
  color: #173d37;
  background: #f8f6ef;
}

.portal-page {
  max-width: 1240px;
  margin: auto;
  padding: 0 32px;
}

header, nav, .actions, footer {
  display: flex;
  align-items: center;
  gap: 20px;
  flex-wrap: wrap;
}

header {
  justify-content: space-between;
  padding: 28px 0;
  border-bottom: 1px solid #dce3de;
}

a {
  color: inherit;
  text-underline-offset: 4px;
}

.brand {
  text-decoration: none;
  font-size: 32px;
  font-weight: 800;
}

.brand span {
  color: #9cbe58;
}

nav a {
  text-decoration: none;
}

select {
  background: white;
  border: 1px solid #bccfc6;
  padding: 10px;
  border-radius: 8px;
}

.portal-hero {
  padding: 80px 0 55px;
  max-width: 960px;
}

.eyebrow {
  text-transform: uppercase;
  letter-spacing: 0.13em;
  font-size: 13px;
  font-weight: 700;
  color: #57736a;
}

h1 {
  font-size: clamp(34px, 5vw, 64px);
  line-height: 1.12;
  letter-spacing: -0.035em;
  margin: 22px 0;
}

h2 {
  font-size: clamp(24px, 3vw, 36px);
  line-height: 1.2;
}

p {
  line-height: 1.75;
  font-size: 17px;
}

.intro {
  font-size: 21px;
  max-width: 850px;
}

.actions {
  margin: 28px 0;
}

.button {
  display: inline-block;
  background: #174e46;
  color: white;
  padding: 15px 22px;
  border: 1px solid #174e46;
  border-radius: 12px;
  text-decoration: none;
  font-weight: 650;
}

.secondary {
  background: transparent;
  color: #174e46;
}

.note {
  font-size: 14px;
  color: #587167;
}

.dedicated {
  display: grid;
  grid-template-columns: 1.2fr 1fr;
  gap: 45px;
  background: #e7efe7;
  padding: 35px;
  border-radius: 24px;
}

.site-example {
  background: #fff;
  padding: 30px;
  border-radius: 16px;
  align-self: center;
  overflow-wrap: anywhere;
}

.site-example strong {
  display: block;
  font-size: clamp(20px, 3vw, 29px);
  margin: 20px 0;
}

section {
  padding: 32px 0;
}

.cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 22px;
}

.cards article {
  background: white;
  border: 1px solid #dce3de;
  border-radius: 18px;
  padding: 28px;
}

.cards article > span {
  font-size: 24px;
  color: #76964c;
}

.cards h3 {
  font-size: 23px;
}

.delegation {
  margin: 35px 0;
  border-block: 1px solid #dce3de;
}

.client-note {
  max-width: 850px;
}

footer {
  border-top: 1px solid #dce3de;
  padding: 30px 0;
  margin-top: 30px;
  font-size: 14px;
}

@media (max-width: 760px) {
  .portal-page {
    padding: 0 20px;
  }
  header {
    gap: 20px;
  }
  nav {
    gap: 14px;
  }
  .portal-hero {
    padding-top: 45px;
  }
  .cards, .dedicated {
    grid-template-columns: 1fr;
  }
  .dedicated {
    padding: 24px;
    gap: 12px;
  }
  .actions a {
    width: 100%;
    text-align: center;
    box-sizing: border-box;
  }
}
.portal-hero--with-image {
  display: grid;
  grid-template-columns: minmax(0, 1.25fr) minmax(0, 1fr);
  align-items: center;
  gap: clamp(24px, 4vw, 56px);
  max-width: none;
}

.portal-hero--with-image h1 {
  font-size: clamp(34px, 4.2vw, 58px);
}

.portal-hero-image {
  display: block;
  width: 100%;
  height: auto;
  aspect-ratio: 4/5;
  object-fit: cover;
  object-position: 65% center;
  border-radius: 24px;
}

@media (max-width: 900px) {
  .portal-hero--with-image {
    grid-template-columns: 1fr;
  }
  .portal-hero-image {
    aspect-ratio: 3/2;
    object-position: center;
  }
}
.store-home {
  max-width: 74rem;
  margin: auto;
  padding: clamp(1rem, 4vw, 3rem);
}

.store-home .intro {
  white-space: pre-line;
  max-width: 65ch;
}

.catalog {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 18rem), 1fr));
  gap: 1rem;
}

.catalog article {
  background: white;
  border: 1px solid #d6e1db;
  border-radius: 1rem;
  padding: 1rem;
}

.catalog img {
  width: 100%;
  aspect-ratio: 16/9;
  object-fit: cover;
  border-radius: 0.65rem;
}

.catalog nav {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
}

.store-home a {
  color: #175449;
}

.owner-hero {
  display: grid;
  grid-template-columns: minmax(0, 1.15fr) minmax(0, 1fr);
  gap: clamp(20px, 5vw, 72px);
  align-items: center;
  padding: clamp(28px, 5vw, 72px) 0 28px;
}

.owner-hero h1 {
  font-size: clamp(38px, 6vw, 76px);
  margin: 12px 0;
  letter-spacing: -0.055em;
}

.owner-hero h1 span {
  color: #416641;
}

.owner-lead {
  max-width: 33ch;
  font-size: clamp(17px, 2vw, 22px);
  line-height: 1.45;
}

.owner-points {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.owner-points div {
  flex: 1 1 135px;
  background: #e7efe2;
  border-radius: 14px;
  padding: 10px 13px;
}

.owner-points strong, .owner-points span {
  display: block;
}

.owner-points strong {
  font-size: clamp(18px, 2.3vw, 28px);
}

.owner-points span {
  font-size: 14px;
}

.owner-hero .actions {
  gap: 10px;
  margin: 20px 0 10px;
}

.owner-photos {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.owner-photos img {
  width: 100%;
  height: auto;
  aspect-ratio: 2/1;
  object-fit: cover;
  border-radius: 14px;
}

.owner-photos .villa {
  grid-column: 1/-1;
  aspect-ratio: 1.65;
  object-position: center;
}

.owner-tools {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
  padding: 8px 0 28px;
}

.owner-tools article {
  padding: clamp(16px, 3vw, 30px);
  background: white;
  border: 1px solid #d4e1d8;
  border-radius: 18px;
}

.owner-tools p, .owner-delegate p {
  line-height: 1.5;
}

.example-address {
  display: inline-block;
  max-width: 100%;
  overflow-wrap: anywhere;
  background: #e7efe2;
  border-radius: 8px;
  padding: 6px 10px;
}

.owner-delegate {
  border-top: 1px solid #d4e1d8;
  padding: 24px 0;
}

.owner-landing a:focus-visible {
  outline: 3px solid #966229;
  outline-offset: 3px;
}

@media (max-width: 760px) {
  .owner-hero, .owner-tools {
    grid-template-columns: 1fr;
  }
  .owner-hero .actions a {
    padding: 12px;
  }
  .owner-photos .villa {
    aspect-ratio: 2;
  }
  .owner-landing footer {
    margin-top: 0;
  }
}
.admin-welcome .button {
  color: #fff;
}

.admin-welcome .admin-public-link {
  display: inline-block;
  margin: 0.75rem;
