import {Injectable} from '@angular/core';import {CanActivate,Router,UrlTree} from '@angular/router';import {AssetAccessService} from './asset-access.service';
@Injectable({providedIn:'root'})export class PlatformAdminGuard implements CanActivate{constructor(private access:AssetAccessService,private router:Router){}async canActivate(_route:any,state:any):Promise<boolean|UrlTree>{if(await this.access.checkPlatformAdmin())return true;return this.router.createUrlTree(['/admin-access'],{queryParams:{reason:this.access.adminAccessFailure||'session_check_failed',returnUrl:state.url}});}}

@Injectable({providedIn:'root'})export class OwnerWorkspaceGuard implements CanActivate{constructor(private access:AssetAccessService,private router:Router){}async canActivate():Promise<boolean|UrlTree>{await this.access.refresh();return this.access.isPlatformAdmin?this.router.parseUrl('/platform/admin'):this.access.isOwner||this.router.parseUrl('/account/bookings');}}

@Injectable({providedIn:'root'})export class ManagementWorkspaceGuard implements CanActivate{constructor(private access:AssetAccessService,private router:Router){}async canActivate():Promise<boolean|UrlTree>{await this.access.refresh();return this.access.isAuthenticated||this.router.parseUrl('/account/login');}}
