import {MessageBadgeComponent} from './message-badge.component';import {unreadConversation} from './message-unread';
import {Router} from '@angular/router';import {AssetAccessService} from '../services/asset-access.service';import {dedicatedAsset} from '../services/asset-domain';import {assetContactText,assetContactScope} from './asset-contact-text';
import {Component,OnInit,OnDestroy} from '@angular/core';import {CommonModule} from '@angular/common';import {RouterModule} from '@angular/router';import {LanguageService} from '../services/language.service';import {messagingText} from './messaging-text';import {MessageNotificationsService} from './message-notifications.service';
const COPY:Record<string,string[]>={fr:['Nouveau message','messages non lus','Fermer la notification'],en:['New message','unread messages','Dismiss notification'],es:['Nuevo mensaje','mensajes sin leer','Cerrar notificación'],it:['Nuovo messaggio','messaggi non letti','Chiudi notifica'],de:['Neue Nachricht','ungelesene Nachrichten','Benachrichtigung schließen'],nl:['Nieuw bericht','ongelezen berichten','Melding sluiten'],ru:['Новое сообщение','непрочитанных сообщений','Закрыть уведомление']};
@Component({selector:'app-message-notifications',standalone:true,imports:[CommonModule,RouterModule,MessageBadgeComponent],template:`<ng-container *ngIf="notifications.uid"><a class="messages-launcher" routerLink="/messages" [queryParams]="destination()" [attr.aria-label]="label()"><span aria-hidden="true">✉</span> {{messageLabel()}} <app-message-badge></app-message-badge></a><section class="message-toast" *ngIf="notifications.notice|async as notice" role="status" aria-live="polite"><a routerLink="/messages" [queryParams]="{threadId:notice.id}" (click)="notifications.dismiss()"><b>{{t(0)}}</b><span>{{notice.assetName}}</span></a><button type="button" (click)="notifications.dismiss()" [attr.aria-label]="t(2)">×</button></section></ng-container>`,styles:[`:host{position:relative;z-index:1050}.messages-launcher{position:fixed;bottom:calc(18px + env(safe-area-inset-bottom));right:18px;display:flex;align-items:center;gap:8px;background:#164f62;color:#fff;padding:12px 16px;border-radius:28px;box-shadow:0 4px 18px #0003;text-decoration:none;font:600 15px/1.4 sans-serif}.messages-launcher strong{min-width:24px;padding:2px 6px;text-align:center;border-radius:20px;background:#f88b20;color:#102f3d}.message-toast{position:fixed;right:18px;bottom:calc(82px + env(safe-area-inset-bottom));max-width:min(340px,calc(100vw - 36px));display:flex;background:white;color:#143d4d;border:1px solid #ccdce1;border-radius:14px;box-shadow:0 5px 24px #0003}.message-toast a{display:flex;flex-direction:column;gap:5px;padding:16px;color:inherit;text-decoration:none;overflow-wrap:anywhere}.message-toast button{align-self:flex-start;border:0;background:none;padding:10px 14px;color:inherit;font-size:24px;cursor:pointer}a:focus-visible,button:focus-visible{outline:3px solid #f88b20;outline-offset:3px}@media print{:host{display:none}}`]})
export class MessageNotificationsComponent implements OnInit,OnDestroy {
 constructor(public notifications:MessageNotificationsService,public language:LanguageService,private router:Router,private access:AssetAccessService){}
 ngOnInit(){this.notifications.start();}ngOnDestroy(){this.notifications.stop();}
 t(i:number){return (COPY[this.language.currentLanguage]||COPY.en)[i];}contactQuery():any{const scope=assetContactScope(this.router.url,dedicatedAsset());return scope&&!this.access.canManageFor(scope.assetType,scope.assetId)?{contactType:scope.assetType,contactAsset:scope.assetId}:{};}destination(){const notice=unreadConversation(this.notifications.summary.value);return notice?{threadId:notice.id}:this.contactQuery();}messageLabel(){return !this.notifications.summary.value.unreadMessages&&this.contactQuery().contactAsset?assetContactText(this.language.currentLanguage,0):messagingText(this.language.currentLanguage,0);}
 label(){const count=this.notifications.summary.value.unreadMessages;return this.messageLabel()+(count?' — '+count+' '+this.t(1):'');}
}
